/// Output of one fixture through both Go type sets.
#[derive(serde::Deserialize, Debug)]
struct GoResult {
    label: String,
    gen_out: Option<Value>,
    hand_out: Option<Value>,
    gen_err: String,
    hand_err: String,
}

#[derive(serde::Deserialize, Debug)]
struct GoRun {
    results: Vec<GoResult>,
    /// `ImageResult.Images.Variant` chosen by the generated Go per label.
    variants: BTreeMap<String, String>,
}

fn copy_go(from: &Path, to: &Path, package_from: &str, package_to: &str) {
    let text = std::fs::read_to_string(from).unwrap();
    std::fs::write(
        to,
        text.replacen(
            &format!("package {package_from}"),
            &format!("package {package_to}"),
            1,
        ),
    )
    .unwrap();
}

/// Build the harness module and run it with real `go`. `mutate` edits the
/// generated types.go before the run.
fn run_go(label: &str, fixtures: &[Fixture], mutate: impl Fn(String) -> String) -> GoRun {
    let dir = std::env::temp_dir().join(format!("aimux-wire-diff-{label}-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    for d in ["gen", "hand"] {
        std::fs::create_dir_all(dir.join(d)).unwrap();
    }
    std::fs::write(dir.join("go.mod"), "module harness\n\ngo 1.24\n").unwrap();
    let model = wire::from_inputs(&Inputs::from_workspace(&workspace())).unwrap();
    for o in Go.emit(&model) {
        if o.path.as_os_str() == "go.mod" {
            continue;
        }
        let content = if o.path.as_os_str() == "types.go" {
            mutate(o.content)
        } else {
            o.content
        };
        std::fs::write(dir.join("gen").join(&o.path), content).unwrap();
    }
    let bindings = workspace().join("bindings/go");
    for f in ["types.go", "multimodal_types.go"] {
        copy_go(
            &bindings.join(f),
            &dir.join("hand").join(f),
            "aimux",
            "hand",
        );
    }
    // types.go names RepairToolCallFunc (repair.go needs cgo); a stub type
    // keeps the copy compiling. It is `json:"-"` and never on the wire.
    std::fs::write(
        dir.join("hand/stub.go"),
        "package hand\n\n// RepairToolCallFunc stands in for bindings/go/repair.go (cgo).\ntype RepairToolCallFunc func()\n",
    )
    .unwrap();
    let mut cases = String::new();
    for t in fixtures.iter().map(|f| f.ty).collect::<BTreeSet<_>>() {
        cases.push_str(&format!(
            "\t\tcase {t:?}:\n\t\t\tr = run[gen.{t}, hand.{t}](f.Label, f.JSON)\n"
        ));
    }
    let main = format!(
        r#"package main

import (
	"encoding/json"
	"os"

	gen "harness/gen"
	"harness/hand"
)

type fixture struct {{
	Label string          `json:"label"`
	Type  string          `json:"type"`
	JSON  json.RawMessage `json:"json"`
}}

type result struct {{
	Label   string          `json:"label"`
	GenOut  json.RawMessage `json:"gen_out"`
	HandOut json.RawMessage `json:"hand_out"`
	GenErr  string          `json:"gen_err"`
	HandErr string          `json:"hand_err"`
}}

func through[T any](in []byte) (json.RawMessage, string) {{
	var v T
	if err := json.Unmarshal(in, &v); err != nil {{
		return nil, "decode: " + err.Error()
	}}
	out, err := json.Marshal(v)
	if err != nil {{
		return nil, "encode: " + err.Error()
	}}
	return out, ""
}}

func run[G any, H any](label string, in []byte) result {{
	r := result{{Label: label}}
	r.GenOut, r.GenErr = through[G](in)
	r.HandOut, r.HandErr = through[H](in)
	return r
}}

func main() {{
	var fixtures []fixture
	data, err := os.ReadFile("fixtures.json")
	if err != nil {{
		panic(err)
	}}
	if err := json.Unmarshal(data, &fixtures); err != nil {{
		panic(err)
	}}
	out := struct {{
		Results  []result         `json:"results"`
		Variants map[string]string `json:"variants"`
	}}{{Variants: map[string]string{{}}}}
	for _, f := range fixtures {{
		var r result
		switch f.Type {{
{cases}		default:
			panic("no Go type for " + f.Type)
		}}
		out.Results = append(out.Results, r)
		if f.Type == "ImageResult" {{
			var g gen.ImageResult
			if json.Unmarshal(f.JSON, &g) == nil {{
				out.Variants[f.Label] = g.Images.Variant
			}}
		}}
	}}
	if err := json.NewEncoder(os.Stdout).Encode(out); err != nil {{
		panic(err)
	}}
}}
"#
    );
    std::fs::write(dir.join("main.go"), main).unwrap();
    let fixtures_json: Vec<Value> = fixtures
        .iter()
        .map(|f| json!({"label": f.label, "type": f.ty, "json": f.json}))
        .collect();
    std::fs::write(
        dir.join("fixtures.json"),
        serde_json::to_string_pretty(&fixtures_json).unwrap(),
    )
    .unwrap();
    let out = Command::new("go")
        .args(["run", "."])
        .current_dir(&dir)
        .output()
        .expect("`go` is required for the Go diff test (it is not skipped when missing)");
    assert!(
        out.status.success(),
        "go run failed:\n{}",
        String::from_utf8_lossy(&out.stderr)
    );
    let run: GoRun = serde_json::from_slice(&out.stdout).unwrap();
    let _ = std::fs::remove_dir_all(&dir);
    run
}

/// One diff row.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct Row {
    ty: String,
    field: String,
    generated: String,
    handwritten: String,
    /// What the Rust serde output has at this path.
    truth: String,
}

const ABSENT: &str = "(absent)";

fn show(v: Option<&Value>) -> String {
    v.map_or_else(|| ABSENT.to_string(), Value::to_string)
}

fn child<'a>(v: Option<&'a Value>, key: &str) -> Option<&'a Value> {
    v.and_then(|v| v.as_object()).and_then(|o| o.get(key))
}

/// Compare `gen` and `hand` at every path of `truth` ∪ `hand`. Keys only
/// the generated output has are returned in `gen_extra`.
fn diff(
    ty: &str,
    path: &str,
    truth: Option<&Value>,
    gen_v: Option<&Value>,
    hand: Option<&Value>,
    rows: &mut Vec<Row>,
    gen_extra: &mut Vec<String>,
) {
    let is_obj = |v: Option<&Value>| v.is_none_or(Value::is_object);
    let is_arr = |v: Option<&Value>| v.is_none_or(Value::is_array);
    let any_some = truth.is_some() || hand.is_some() || gen_v.is_some();
    let join = |k: &str| {
        if path.is_empty() {
            k.to_string()
        } else {
            format!("{path}.{k}")
        }
    };
    if any_some
        && is_obj(truth)
        && is_obj(gen_v)
        && is_obj(hand)
        && [truth, gen_v, hand]
            .iter()
            .any(|v| v.is_some_and(Value::is_object))
    {
        let mut keys = BTreeSet::new();
        for v in [truth, hand].into_iter().flatten() {
            keys.extend(v.as_object().unwrap().keys().cloned());
        }
        if let Some(g) = gen_v {
            for k in g.as_object().unwrap().keys() {
                if !keys.contains(k) {
                    gen_extra.push(format!("{ty}.{}", join(k)));
                }
            }
        }
        for k in keys {
            diff(
                ty,
                &join(&k),
                child(truth, &k),
                child(gen_v, &k),
                child(hand, &k),
                rows,
                gen_extra,
            );
        }
        return;
    }
    if any_some
        && is_arr(truth)
        && is_arr(gen_v)
        && is_arr(hand)
        && [truth, gen_v, hand]
            .iter()
            .any(|v| v.is_some_and(|x| x.as_array().is_some_and(|a| !a.is_empty())))
    {
        let len = [truth, gen_v, hand]
            .iter()
            .map(|v| v.and_then(Value::as_array).map_or(0, Vec::len))
            .max()
            .unwrap_or(0);
        for i in 0..len {
            fn at(v: Option<&Value>, i: usize) -> Option<&Value> {
                v.and_then(Value::as_array).and_then(|a| a.get(i))
            }
            diff(
                ty,
                &format!("{path}[{i}]"),
                at(truth, i),
                at(gen_v, i),
                at(hand, i),
                rows,
                gen_extra,
            );
        }
        return;
    }
    if gen_v != hand {
        rows.push(Row {
            ty: ty.to_string(),
            field: if path.is_empty() {
                "(value)".into()
            } else {
                path.to_string()
            },
            generated: show(gen_v),
            handwritten: show(hand),
            truth: show(truth),
        });
    }
}

struct Compared {
    rows: Vec<Row>,
    gen_extra: Vec<String>,
    /// Fixtures where the generated Go output differs from the Rust output.
    gen_mismatch: Vec<String>,
    errors: Vec<String>,
}

fn compare(fixtures: &[Fixture], run: &GoRun) -> Compared {
    let mut c = Compared {
        rows: Vec::new(),
        gen_extra: Vec::new(),
        gen_mismatch: Vec::new(),
        errors: Vec::new(),
    };
    for f in fixtures {
        let r = run.results.iter().find(|r| r.label == f.label).unwrap();
        if !r.gen_err.is_empty() {
            c.errors
                .push(format!("{} (generated): {}", f.label, r.gen_err));
        }
        if !r.hand_err.is_empty() {
            c.rows.push(Row {
                ty: f.ty.into(),
                field: "(decode)".into(),
                generated: "ok".into(),
                handwritten: r.hand_err.clone(),
                truth: "ok".into(),
            });
        }
        if r.gen_out.as_ref() != Some(&f.json) {
            c.gen_mismatch.push(format!(
                "{}: rust {} != generated {}",
                f.label,
                f.json,
                show(r.gen_out.as_ref())
            ));
        }
        diff(
            f.ty,
            "",
            Some(&f.json),
            r.gen_out.as_ref(),
            r.hand_out.as_ref(),
            &mut c.rows,
            &mut c.gen_extra,
        );
    }
    c.rows.sort();
    c.rows.dedup_by(|a, b| a.ty == b.ty && a.field == b.field);
    c
}

/// `[Type]` sections with `"field" = "verdict"` lines (a TOML subset).
fn verdicts(text: &str) -> BTreeMap<(String, String), String> {
    let mut out = BTreeMap::new();
    let mut section = String::new();
    for line in text.lines().map(str::trim) {
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        if let Some(s) = line.strip_prefix('[').and_then(|l| l.strip_suffix(']')) {
            section = s.trim().to_string();
            continue;
        }
        let (k, v) = line.split_once('=').expect("`\"field\" = \"verdict\"`");
        let unq = |s: &str| s.trim().trim_matches('"').to_string();
        out.insert((section.clone(), unq(k)), unq(v));
    }
    out
}

fn expected_verdict(r: &Row) -> &'static str {
    if r.generated == r.truth {
        "handwritten bug"
    } else {
        "generator bug"
    }
}

fn cell(s: &str) -> String {
    format!("`{}`", s.replace('|', "\\|"))
}

fn render(
    fixtures: &[Fixture],
    run: &GoRun,
    rows: &[Row],
    v: &BTreeMap<(String, String), String>,
) -> String {
    let mut s = String::from(
        "<!-- Generated by tools/aimux-codegen/tests/wire_diff_go.rs; do not edit.\n     Regenerate: AIMUX_BLESS_DIFF=1 cargo test -p aimux-codegen --test wire_diff_go\n     Verdicts: docs/plan/2.2-diff-go-verdicts.toml -->\n\n# 2.2: generated Go vs hand-written Go\n\n",
    );
    s.push_str("Each fixture is a real aimux-core value serialized with serde (the truth). It is decoded and re-marshaled by the generated Go (`aimux-codegen --emit go`) and by the hand-written `bindings/go/types.go` + `multimodal_types.go`. A row is a JSON path where the two outputs differ. The verdict says which side disagrees with the Rust output. The test also requires the generated output to equal the Rust output for every fixture.\n\n");
    s.push_str("## Fixtures\n\n| label | type | serde output |\n|---|---|---|\n");
    for f in fixtures {
        s.push_str(&format!(
            "| {} | {} | {} |\n",
            f.label,
            f.ty,
            cell(&f.json.to_string())
        ));
    }
    s.push_str("\nUntagged overlap: `image-result-overlap` has `\"images\":[]`, which is a valid `Base64(Vec<String>)` and a valid `Binary(Vec<Vec<u8>>)` (`ImageOutputs`, image_model.rs). serde picks the first declared variant. The generated Go picked: ");
    let picked: Vec<String> = run
        .variants
        .iter()
        .map(|(k, v)| format!("`{k}` → `{v}`"))
        .collect();
    s.push_str(&picked.join(", "));
    s.push_str(".\n\n## Diff\n\n| type | field | generated | handwritten | verdict |\n|---|---|---|---|---|\n");
    for r in rows {
        let verdict = v
            .get(&(r.ty.clone(), r.field.clone()))
            .map_or("(missing)", String::as_str);
        s.push_str(&format!(
            "| {} | {} | {} | {} | {verdict} |\n",
            r.ty,
            cell(&r.field),
            cell(&r.generated),
            cell(&r.handwritten)
        ));
    }
    let mut counts: BTreeMap<String, usize> = BTreeMap::new();
    for r in rows {
        if let Some(x) = v.get(&(r.ty.clone(), r.field.clone())) {
            *counts.entry(x.clone()).or_default() += 1;
        }
    }
    s.push_str(&format!("\nRows: {}", rows.len()));
    for (k, n) in &counts {
        s.push_str(&format!("; {k}: {n}"));
    }
    s.push_str(".\n");
    s
}

#[test]
fn generated_go_matches_rust_and_diff_doc_is_current() {
    let fixtures = fixtures();
    let run = run_go("main", &fixtures, |s| s);
    let c = compare(&fixtures, &run);
    assert!(c.errors.is_empty(), "generated Go failed: {:#?}", c.errors);
    assert!(
        c.gen_mismatch.is_empty(),
        "generator bugs (generated Go != Rust serde output): {:#?}",
        c.gen_mismatch
    );
    assert!(
        c.gen_extra.is_empty(),
        "generated-only keys: {:?}",
        c.gen_extra
    );
    assert_eq!(
        run.variants.get("image-result-overlap").map(String::as_str),
        Some("Base64"),
        "untagged overlap must follow declaration order"
    );
    assert_eq!(
        run.variants.get("image-result-binary").map(String::as_str),
        Some("Binary")
    );

    let vpath = workspace().join("docs/plan/2.2-diff-go-verdicts.toml");
    let v = verdicts(&std::fs::read_to_string(&vpath).unwrap_or_default());
    let mut problems = Vec::new();
    for r in &c.rows {
        match v.get(&(r.ty.clone(), r.field.clone())) {
            None => problems.push(format!("no verdict for {} | {}", r.ty, r.field)),
            Some(x) if x != "generator bug" && x != "handwritten bug" => {
                problems.push(format!("bad verdict `{x}` for {} | {}", r.ty, r.field));
            }
            Some(x) if x != expected_verdict(r) => problems.push(format!(
                "verdict `{x}` for {} | {} contradicts the Rust output {}",
                r.ty, r.field, r.truth
            )),
            Some(_) => {}
        }
    }
    for (ty, field) in v.keys() {
        if !c.rows.iter().any(|r| &r.ty == ty && &r.field == field) {
            problems.push(format!(
                "stale verdict for {ty} | {field} (no such diff row)"
            ));
        }
    }
    let doc = render(&fixtures, &run, &c.rows, &v);
    let dpath = workspace().join("docs/plan/2.2-diff-go.md");
    if std::env::var_os("AIMUX_BLESS_DIFF").is_some() {
        std::fs::write(&dpath, &doc).unwrap();
    } else if std::fs::read_to_string(&dpath).ok().as_deref() != Some(doc.as_str()) {
        problems.push(format!(
            "{} is out of date; run AIMUX_BLESS_DIFF=1 cargo test -p aimux-codegen --test wire_diff_go",
            dpath.display()
        ));
    }
    assert!(problems.is_empty(), "{problems:#?}");
}

/// Mutation: rename one wire name in the generated Go (`ToolCall.toolCallId`
/// → `toolCallID`). The comparison reports exactly that one row, and the
/// generator check flags it.
#[test]
fn mutated_wire_name_is_reported_as_exactly_one_row() {
    let fixtures = fixtures();
    let base = compare(&fixtures, &run_go("base", &fixtures, |s| s));
    let mutated_run = run_go("mutated", &fixtures, |s| {
        let start = s.find("\ntype ToolCall struct {").expect("ToolCall struct");
        let end = start + s[start..].find("\n}\n").unwrap();
        let block = &s[start..end];
        let from = "`json:\"toolCallId\"`";
        assert!(block.contains(from), "{block}");
        format!(
            "{}{}{}",
            &s[..start],
            block.replacen(from, "`json:\"toolCallID\"`", 1),
            &s[end..]
        )
    });
    let mutated = compare(&fixtures, &mutated_run);
    let new: Vec<&Row> = mutated
        .rows
        .iter()
        .filter(|r| !base.rows.contains(r))
        .collect();
    assert_eq!(
        new,
        vec![&Row {
            ty: "ToolCall".into(),
            field: "toolCallId".into(),
            generated: ABSENT.into(),
            handwritten: "\"call_1\"".into(),
            truth: "\"call_1\"".into(),
        }]
    );
    assert_eq!(expected_verdict(new[0]), "generator bug");
    assert_eq!(mutated.gen_extra, vec!["ToolCall.toolCallID".to_string()]);
    assert_eq!(mutated.gen_mismatch.len(), 1, "{:?}", mutated.gen_mismatch);
    assert!(mutated.gen_mismatch[0].starts_with("tool-call:"));
}
